import { useState, useEffect } from 'react';
import { X, Check, Edit2, AlertTriangle, Info } from 'lucide-react';

export interface INSAdditive {
  code: string;
  name: string;
  risk: string;
}

export interface OCRAnalysisResponse {
  product_name: string;
  raw_ocr_text: string;
  parsed_ingredients: string[];
  detected_ins_additives: INSAdditive[];
  flagged_allergens: string[];
  nutrition_per_100g: Record<string, number>;
  requires_user_review: boolean;
}

interface IngredientReviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (data: OCRAnalysisResponse) => void;
  initialData: OCRAnalysisResponse;
  isUncataloged?: boolean;
}

export default function IngredientReviewModal({
  isOpen,
  onClose,
  onConfirm,
  initialData,
  isUncataloged = true,
}: IngredientReviewModalProps) {
  const [data, setData] = useState<OCRAnalysisResponse>(initialData);

  useEffect(() => {
    setData(initialData);
  }, [initialData]);

  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        onClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const handleIngredientChange = (index: number, value: string) => {
    const updated = [...data.parsed_ingredients];
    updated[index] = value;
    setData({ ...data, parsed_ingredients: updated });
  };

  const handleAllergenChange = (index: number, value: string) => {
    const updated = [...data.flagged_allergens];
    updated[index] = value;
    setData({ ...data, flagged_allergens: updated });
  };

  const handleConfirm = () => {
    onConfirm({ ...data, requires_user_review: false });
  };

  return (
    <div 
      className="fixed inset-0 z-50 flex items-end justify-center bg-black/60 backdrop-blur-sm sm:items-center p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="review-modal-title"
    >
      <div className="w-full max-w-2xl bg-zinc-900 border-2 border-zinc-700 rounded-2xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4">
        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-zinc-800 bg-zinc-950">
          <div>
            <h2 id="review-modal-title" className="text-xl font-bold text-zinc-100 flex items-center gap-2">
              <Edit2 className="w-5 h-5 text-emerald-400" />
              Review Scan Results
            </h2>
            <p className="text-sm text-zinc-400 mt-1">Please verify the extracted information below.</p>
          </div>
          <button
            onClick={onClose}
            className="p-2 text-zinc-400 hover:text-white hover:bg-zinc-800 rounded-full transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center focus-visible:outline-2 focus-visible:outline-emerald-400"
            aria-label="Close review dialog"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="p-6 max-h-[60vh] overflow-y-auto space-y-8">

          {/* Ingredients Section */}
          <section>
            <h3 className="text-sm font-semibold text-zinc-300 uppercase tracking-wider mb-3">Ingredients</h3>
            <div className="space-y-2">
              {data.parsed_ingredients.map((ing, idx) => (
                <div key={idx} className="flex gap-2">
                  <input
                    type="text"
                    value={ing}
                    onChange={(e) => handleIngredientChange(idx, e.target.value)}
                    className="flex-1 bg-zinc-800 text-zinc-100 border border-zinc-700 rounded-lg px-3 py-2 focus:outline-none focus:border-emerald-500 transition-colors"
                  />
                </div>
              ))}
            </div>
          </section>

          {/* Additives Section */}
          <section>
            <h3 className="text-sm font-semibold text-zinc-300 uppercase tracking-wider mb-3 flex items-center gap-2">
              <Info className="w-4 h-4 text-amber-400" />
              Detected INS Additives
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {data.detected_ins_additives.map((add, idx) => (
                <div key={idx} className="bg-zinc-800/50 border border-zinc-700 rounded-lg p-3">
                  <div className="text-xs text-zinc-500 font-mono">{add.code}</div>
                  <div className="text-sm text-zinc-200 font-medium">{add.name}</div>
                  <div className={`text-xs mt-1 font-semibold ${
                    add.risk === 'high' ? 'text-red-400' :
                    add.risk === 'moderate' ? 'text-amber-400' : 'text-emerald-400'
                  }`}>
                    {add.risk.toUpperCase()} RISK
                  </div>
                </div>
              ))}
              {data.detected_ins_additives.length === 0 && (
                <div className="text-sm text-zinc-500 col-span-2">No specific additives detected.</div>
              )}
            </div>
          </section>

          {/* Allergens Section */}
          <section>
            <h3 className="text-sm font-semibold text-zinc-300 uppercase tracking-wider mb-3 flex items-center gap-2">
              <AlertTriangle className="w-4 h-4 text-red-400" />
              Flagged Allergens
            </h3>
            <div className="flex flex-wrap gap-2">
              {data.flagged_allergens.map((allergen, idx) => (
                <div key={idx} className="flex items-center gap-2 bg-red-500/10 border border-red-500/30 rounded-full pl-3 pr-2 py-1">
                  <input
                    type="text"
                    value={allergen}
                    onChange={(e) => handleAllergenChange(idx, e.target.value)}
                    className="bg-transparent text-sm text-red-300 focus:outline-none w-20"
                  />
                </div>
              ))}
              {data.flagged_allergens.length === 0 && (
                <div className="text-sm text-zinc-500">No allergens flagged.</div>
              )}
            </div>
          </section>

        </div>

        {/* Crowdsourced Food Ingestion Disclosure */}
        {isUncataloged && (
          <div className="mx-6 mb-2 p-4 bg-slate-800/60 border border-slate-700 rounded-2xl text-xs text-gray-300 leading-relaxed flex items-start gap-3">
            <Info className="w-5 h-5 text-emerald-400 shrink-0 mt-0.5" />
            <div className="space-y-1">
              <p className="font-bold text-white text-xs">Crowdsourced Database Ingestion Disclosure</p>
              <p className="text-gray-400">
                This product is not yet in our global database. Submitting will save it privately to your vault while anonymized ingredient details are queued for admin safety review.
              </p>
            </div>
          </div>
        )}

        {/* Footer Actions */}
        <div className="p-4 border-t border-zinc-800 bg-zinc-950 flex justify-end gap-3">
          <button
            type="button"
            onClick={onClose}
            className="min-h-[44px] px-5 py-2.5 rounded-xl text-sm font-medium text-zinc-300 hover:bg-zinc-800 transition-colors focus-visible:outline-2 focus-visible:outline-emerald-400"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={handleConfirm}
            className="min-h-[44px] px-5 py-2.5 rounded-xl text-sm font-bold bg-emerald-500 text-zinc-950 hover:bg-emerald-400 flex items-center gap-2 transition-colors shadow-md focus-visible:outline-2 focus-visible:outline-emerald-400 cursor-pointer"
          >
            <Check className="w-4 h-4" />
            Confirm & Score
          </button>
        </div>
      </div>
    </div>
  );
}

﻿import React, { useState, useEffect, useRef } from 'react';
import { Quote } from '../quotesData';
import {
  getNextQuote,
  markQuoteAsDisplayed,
  toggleSaveQuote,
  getSavedQuotes,
  QuoteRecord
} from '../quoteEngine';
import { Heart, Sparkles, Bookmark, ArrowRight, X, Flame } from 'lucide-react';


// Helper to calculate dynamic quote display duration:
// 8 seconds for short/single line quotes, 15 seconds for long or comma-separated/multi-sentence quotes.
export const getQuoteDurationSeconds = (quoteText?: string): number => {
  if (!quoteText) return 8;
  const trimmed = quoteText.trim();
  const isLongOrMultiClause =
    trimmed.includes(',') ||
    trimmed.includes(';') ||
    (trimmed.match(/[.!?]/g) || []).length > 1 ||
    trimmed.length > 60;
  return isLongOrMultiClause ? 15 : 8;
};

interface InteractiveQuoteCardProps {
  userStreakDays?: number;
}

export const InteractiveQuoteCard: React.FC<InteractiveQuoteCardProps> = ({
  userStreakDays = 1
}) => {
  const [currentQuote, setCurrentQuote] = useState<Quote | null>(null);
  const [quoteRecord, setQuoteRecord] = useState<QuoteRecord | null>(null);
  const [isSaved, setIsSaved] = useState(false);
  const [showSavedModal, setShowSavedModal] = useState(false);
  const [savedQuotesList, setSavedQuotesList] = useState<Quote[]>([]);
  const [key, setKey] = useState(0);

  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const loadNextQuote = () => {
    const { quote } = getNextQuote(currentQuote?.id);
    setCurrentQuote(quote);

    const updatedHistory = markQuoteAsDisplayed(quote.id);
    const updatedRecord = updatedHistory[quote.id];
    setQuoteRecord(updatedRecord);
    setIsSaved(!!updatedRecord?.isSaved);
    setKey(prev => prev + 1);
  };

  const currentDurationSec = getQuoteDurationSeconds(currentQuote?.text);

  useEffect(() => {
    loadNextQuote();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!currentQuote) return;

    if (timerRef.current) clearTimeout(timerRef.current);

    timerRef.current = setTimeout(() => {
      loadNextQuote();
    }, currentDurationSec * 1000);

    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentQuote]);

  const handleNextClick = () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    loadNextQuote();
  };

  const handleToggleSave = () => {
    if (!currentQuote) return;
    const newSaved = toggleSaveQuote(currentQuote.id);
    setIsSaved(newSaved);
  };

  const handleOpenSavedModal = () => {
    setSavedQuotesList(getSavedQuotes());
    setShowSavedModal(true);
  };

  const displayCount = quoteRecord?.displayCount || 1;
  const cooldownDays = displayCount * 3;

  return (
    <div className="w-full bg-slate-900/90 border border-slate-800 rounded-3xl p-6 sm:p-8 shadow-2xl space-y-5 relative overflow-hidden backdrop-blur-xl mb-8">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-2">
        <div className="flex items-center gap-2">
          <span className="text-[11px] font-extrabold tracking-wider text-emerald-400 bg-emerald-500/10 px-3 py-1 rounded-md uppercase border border-emerald-500/20">
            ✨ {currentQuote?.category || 'WELLNESS'}
          </span>
          <div className="flex items-center gap-1 bg-amber-500/10 border border-amber-500/30 rounded-full px-2.5 py-0.5 text-xs font-bold text-amber-400">
            <Flame className="w-3.5 h-3.5 fill-amber-400 text-amber-400" />
            <span>{userStreakDays} Days Streak</span>
          </div>
        </div>

        <span className="text-[11px] font-semibold text-slate-400 bg-slate-800/80 px-3 py-1 rounded-md border border-slate-700/50">
          ⏳ Cooldown Rule: {cooldownDays} Days (View #{displayCount})
        </span>
      </div>

      {/* Quote Content */}
      <p className="text-lg sm:text-xl font-bold text-slate-100 leading-relaxed italic text-left">
        &ldquo;{currentQuote?.text || 'Loading motivational quote...'}&rdquo;
      </p>

      <p className="text-xs sm:text-sm font-semibold text-slate-400 text-right">
        — {currentQuote?.author || 'Z-SeHealth'}
      </p>

      {/* 7-Second Animated Progress Bar */}
      <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
        <div
          key={key}
          className="h-full bg-emerald-500 transition-all"
          style={{
            animation: `progressFill ${currentDurationSec}s linear 1 forwards`
          }}
        />
      </div>

      {/* Controls */}
      <div className="flex flex-wrap items-center gap-3 pt-1">
        <button
          onClick={handleToggleSave}
          className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all border ${
            isSaved
              ? 'border-rose-500/50 bg-rose-500/10 text-rose-400'
              : 'border-slate-700 bg-slate-800/50 text-slate-300 hover:bg-slate-800'
          }`}
        >
          <Heart className={`w-4 h-4 ${isSaved ? 'fill-rose-400 text-rose-400' : ''}`} />
          <span>{isSaved ? 'Saved to Deck' : 'Save Quote'}</span>
        </button>

        <button
          onClick={handleNextClick}
          className="flex items-center gap-2 px-5 py-2 rounded-xl bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-extrabold text-xs transition-all shadow-lg shadow-emerald-500/20"
        >
          <span>Next Quote</span>
          <ArrowRight className="w-4 h-4" />
        </button>

        <button
          onClick={handleOpenSavedModal}
          className="flex items-center gap-2 px-4 py-2 rounded-xl border border-slate-700 bg-slate-800/40 text-slate-300 hover:bg-slate-800 text-xs font-semibold sm:ml-auto"
        >
          <Bookmark className="w-4 h-4 text-emerald-400" />
          <span>Saved Deck ({getSavedQuotes().length})</span>
        </button>
      </div>

      {/* Saved Quotes Modal */}
      {showSavedModal && (
        <div
          className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4"
          onClick={() => setShowSavedModal(false)}
        >
          <div
            className="w-full max-w-lg bg-slate-900 border border-slate-800 rounded-3xl p-6 space-y-4 max-h-[80vh] flex flex-col"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex items-center justify-between border-b border-slate-800 pb-3">
              <h3 className="text-base font-bold text-white flex items-center gap-2">
                <Bookmark className="w-5 h-5 text-rose-400 fill-rose-400" />
                <span>Your Saved Quotes Deck</span>
              </h3>
              <button
                onClick={() => setShowSavedModal(false)}
                className="text-slate-400 hover:text-white"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="overflow-y-auto space-y-3 flex-1 pr-1 text-left">
              {savedQuotesList.length === 0 ? (
                <p className="text-center text-sm text-slate-500 py-8 italic">
                  No saved quotes yet. Click &quot;Save Quote&quot; on any quote!
                </p>
              ) : (
                savedQuotesList.map((q) => (
                  <div key={q.id} className="p-4 bg-slate-800/60 rounded-2xl border border-slate-700/50 space-y-1">
                    <p className="text-sm font-semibold text-slate-200">&ldquo;{q.text}&rdquo;</p>
                    <span className="text-xs font-medium text-slate-400 block text-right">— {q.author}</span>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

interface LandingLoadingOverlayProps {
