                          <button 
                            onClick={() => { setCustomMacros(null); setIsCustomizingMacros(false); }}
                            className="text-[10px] font-bold px-2 py-1 rounded bg-slate-700/50 hover:bg-slate-700 text-gray-300 transition-colors uppercase tracking-wide"
