import { useState, useEffect, useCallback } from 'react';
import {
  Smartphone,
  Send,
  RotateCcw,
  RefreshCw,
  AlertTriangle,
  CheckCircle2,
  GitBranch,
} from 'lucide-react';
import { useAdminAuth } from '../../../context/AdminAuthContext';
import { API_BASE } from '../../../config';

interface UpdateItem {
  id: string;
  createdAt: string;
  group?: string;
  message: string;
  runtimeVersion: string;
  platform: string;
}

export default function AdminOtaManager() {
  const { getAdminAuthHeader, permissions } = useAdminAuth();
  const [channel, setChannel] = useState<'production' | 'staging'>('production');
  const [updates, setUpdates] = useState<UpdateItem[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [dispatchMessage, setDispatchMessage] = useState<string>('');
  const [statusText, setStatusText] = useState<string | null>(null);
  const [isError, setIsError] = useState<boolean>(false);

  const fetchUpdates = useCallback(async () => {
    setLoading(true);
    setStatusText(null);
    setIsError(false);

    try {
      const headers = await getAdminAuthHeader();
      const res = await fetch(`${API_BASE}/api/admin/ota/releases?channel=${channel}`, {
        headers,
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.detail || err.error || `HTTP ${res.status}`);
      }

      const data = await res.json();
      setUpdates(data.updates || []);
      setStatusText(`Fetched ${data.updates?.length || 0} active releases for channel: [${channel.toUpperCase()}]`);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Fetch failed';
      setStatusText(`Error: ${msg}`);
      setIsError(true);
    } finally {
      setLoading(false);
    }
  }, [channel, getAdminAuthHeader]);

  useEffect(() => {
    fetchUpdates();
  }, [fetchUpdates]);

  const triggerDispatch = async (action: 'publish' | 'rollback' = 'publish') => {
    if (!permissions.canTriggerOTA) {
      setStatusText('Permission Denied: You do not possess EAS OTA dispatch capabilities.');
      setIsError(true);
      return;
    }

    if (action === 'publish' && !dispatchMessage.trim()) {
      setStatusText('Please enter a hotfix message or commit note.');
      setIsError(true);
      return;
    }

    setLoading(true);
    setStatusText(null);
    setIsError(false);

    try {
      const headers = await getAdminAuthHeader();
      const res = await fetch(`${API_BASE}/api/admin/ota/dispatch`, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          channel,
          message: action === 'rollback' ? 'Emergency OTA Rollback triggered from Admin Portal' : dispatchMessage.trim(),
          action,
        }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.detail || data.error || 'Failed to dispatch OTA');
      }

      setStatusText(`Success: ${data.message}`);
      setDispatchMessage('');
      fetchUpdates();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Dispatch failed';
      setStatusText(`Error: ${msg}`);
      setIsError(true);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 border-b border-slate-800 pb-5">
        <div>
          <div className="flex items-center gap-2">
            <Smartphone className="w-4 h-4 text-emerald-400" />
            <span className="text-[11px] font-mono uppercase tracking-widest text-emerald-400 font-bold">
              React Native Expo / EAS Distribution
            </span>
          </div>
          <h2 className="text-2xl font-black font-outfit uppercase tracking-tight text-white mt-1">
            Over-The-Air (OTA) Hotfix Manager
          </h2>
          <p className="text-xs text-slate-400 font-mono">
            Dispatch zero-downtime runtime bundle hotfixes to mobile clients via GitHub Actions CI/CD
          </p>
        </div>

        {/* Channel Switcher */}
        <div className="flex gap-2">
          <button
            onClick={() => setChannel('production')}
            className={`px-4 py-2 rounded-xl text-xs font-bold uppercase transition-all cursor-pointer ${
              channel === 'production'
                ? 'bg-emerald-500 text-slate-950 font-black shadow-lg shadow-emerald-950'
                : 'bg-slate-900 text-slate-400 border border-slate-800 hover:border-slate-700'
            }`}
          >
            Production
          </button>
          <button
            onClick={() => setChannel('staging')}
            className={`px-4 py-2 rounded-xl text-xs font-bold uppercase transition-all cursor-pointer ${
              channel === 'staging'
                ? 'bg-amber-400 text-slate-950 font-black shadow-lg shadow-amber-950'
                : 'bg-slate-900 text-slate-400 border border-slate-800 hover:border-slate-700'
            }`}
          >
            Staging
          </button>
        </div>
      </div>

      {/* Status Notice */}
      {statusText && (
        <div
          className={`p-4 rounded-2xl border text-xs font-mono flex items-center gap-3 ${
            isError
              ? 'bg-rose-500/10 border-rose-500/30 text-rose-300'
              : 'bg-emerald-500/10 border-emerald-500/30 text-emerald-300'
          }`}
        >
          {isError ? (
            <AlertTriangle className="w-4 h-4 shrink-0 text-rose-400" />
          ) : (
            <CheckCircle2 className="w-4 h-4 shrink-0 text-emerald-400" />
          )}
          <span>{statusText}</span>
        </div>
      )}

      {/* Dispatch Action Card */}
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-6 sm:p-7 shadow-2xl">
        <div className="flex items-center gap-2 mb-2">
          <GitBranch className="w-4 h-4 text-emerald-400" />
          <h3 className="text-base font-bold font-outfit uppercase tracking-tight text-white">
            Dispatch Instant Remote Hotfix
          </h3>
        </div>
        <p className="text-xs text-slate-400 mb-4">
          Publishes an immediate OTA bundle update without requiring an app store review. Locked to runtimeVersion policy.
        </p>

        <div className="flex flex-col sm:flex-row gap-3">
          <input
            type="text"
            placeholder="Commit / hotfix note (e.g., Fix quote progress bar 8s/15s algorithm)..."
            value={dispatchMessage}
            onChange={(e) => setDispatchMessage(e.target.value)}
            disabled={!permissions.canTriggerOTA}
            className="flex-1 bg-slate-950 border border-slate-800 rounded-2xl px-4 py-2.5 text-xs text-white placeholder-slate-600 focus:outline-none focus:border-emerald-500 font-mono disabled:opacity-50"
          />
          <button
            onClick={() => triggerDispatch('publish')}
            disabled={loading || !permissions.canTriggerOTA}
            className="px-5 py-2.5 bg-emerald-500 hover:bg-emerald-400 text-slate-950 text-xs font-black uppercase tracking-wider rounded-2xl transition-all flex items-center justify-center gap-2 active:scale-95 shadow-lg shadow-emerald-950 cursor-pointer disabled:opacity-50"
          >
            <Send className="w-4 h-4" />
            Deploy OTA
          </button>
          <button
            onClick={() => triggerDispatch('rollback')}
            disabled={loading || !permissions.canTriggerOTA}
            className="px-4 py-2.5 bg-rose-500/10 hover:bg-rose-500/20 border border-rose-500/30 text-rose-300 text-xs font-bold uppercase tracking-wider rounded-2xl transition-all flex items-center justify-center gap-2 active:scale-95 cursor-pointer disabled:opacity-50"
          >
            <RotateCcw className="w-4 h-4 text-rose-400" />
            Rollback
          </button>
        </div>
      </div>

      {/* Active Releases Table */}
      <div className="bg-slate-900 border border-slate-800 rounded-3xl overflow-hidden shadow-2xl">
        <div className="p-5 border-b border-slate-800 flex justify-between items-center">
          <div>
            <h4 className="text-xs font-black font-mono uppercase tracking-widest text-slate-400">
              Active Releases on [{channel.toUpperCase()}]
            </h4>
            <p className="text-[11px] text-slate-500 font-mono mt-0.5">
              Querying Expo Application Services updates API
            </p>
          </div>
          <button
            onClick={fetchUpdates}
            disabled={loading}
            className="p-2 rounded-xl bg-slate-950 border border-slate-800 text-slate-400 hover:text-white cursor-pointer"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs border-collapse">
            <thead>
              <tr className="border-b border-slate-800 text-slate-500 font-mono text-[10px] uppercase tracking-wider bg-slate-950/40">
                <th className="py-3 px-4">Update ID</th>
                <th className="py-3 px-4">Runtime</th>
                <th className="py-3 px-4">Hotfix Message</th>
                <th className="py-3 px-4">Timestamp</th>
                <th className="py-3 px-4">Platform</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/60 font-sans">
              {updates.length === 0 ? (
                <tr>
                  <td colSpan={5} className="py-10 text-center text-slate-600 font-mono text-xs">
                    {loading ? 'Querying EAS...' : 'No update releases recorded for this channel.'}
                  </td>
                </tr>
              ) : (
                updates.map((item) => (
                  <tr key={item.id} className="hover:bg-slate-950/40 transition-colors">
                    <td className="py-3 px-4 font-mono text-emerald-400 font-bold">
                      {item.id.slice(0, 12)}
                    </td>
                    <td className="py-3 px-4 font-mono text-slate-400">{item.runtimeVersion}</td>
                    <td className="py-3 px-4 text-slate-200">{item.message}</td>
                    <td className="py-3 px-4 font-mono text-slate-400 text-[11px]">
                      {item.createdAt ? new Date(item.createdAt).toLocaleString() : 'N/A'}
                    </td>
                    <td className="py-3 px-4 font-mono uppercase text-slate-400">{item.platform}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import {
  UserPlus,
  RefreshCw,
  Trash2,
  Lock,
  Crown,
  CheckCircle2,
  AlertTriangle,
  FileEdit,
} from 'lucide-react';
import { useAdminAuth, AdminUser, AdminPermissions } from '../../../context/AdminAuthContext';
import { API_BASE } from '../../../config';
import { ConfirmModal } from '../../ui/ConfirmModal';

export default function AdminTeamTab() {
  const { isSuperAdmin, getAdminAuthHeader } = useAdminAuth();
  const [team, setTeam] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [actionLoading, setActionLoading] = useState<boolean>(false);
  const [notice, setNotice] = useState<{ text: string; type: 'success' | 'error' } | null>(null);

  // Revoke Admin Modal State
  const [adminToRevoke, setAdminToRevoke] = useState<AdminUser | null>(null);

  // Invite Modal State
  const [inviteModalOpen, setInviteModalOpen] = useState<boolean>(false);
  const [inviteEmail, setInviteEmail] = useState<string>('');
  const [inviteName, setInviteName] = useState<string>('');
  const [invitePerms, setInvitePerms] = useState<AdminPermissions>({
    canManageAdmins: false,
    canManageUsers: true,
    canApproveFoods: true,
    canTriggerOTA: false,
    canViewRevenue: false,
    canViewLogs: true,
  });

  // Edit Permissions Modal State
  const [editingAdmin, setEditingAdmin] = useState<AdminUser | null>(null);
  const [editPerms, setEditPerms] = useState<AdminPermissions>({
    canManageAdmins: false,
    canManageUsers: true,
    canApproveFoods: true,
    canTriggerOTA: false,
    canViewRevenue: false,
    canViewLogs: true,
  });
  const [editActive, setEditActive] = useState<boolean>(true);

  const fetchTeam = useCallback(async () => {
    if (!isSuperAdmin) return;
    setLoading(true);
    setNotice(null);
    try {
      const headers = await getAdminAuthHeader();
      const res = await fetch(`${API_BASE}/api/admin/team`, { headers });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data: AdminUser[] = await res.json();
      setTeam(data);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Failed to fetch admin team';
      setNotice({ text: msg, type: 'error' });
    } finally {
      setLoading(false);
    }
  }, [getAdminAuthHeader, isSuperAdmin]);

  useEffect(() => {
    fetchTeam();
  }, [fetchTeam]);

  // Guard for non-super admins
  if (!isSuperAdmin) {
    return (
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-12 text-center max-w-xl mx-auto space-y-4">
        <div className="w-16 h-16 rounded-3xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center mx-auto text-amber-400">
          <Lock className="w-8 h-8" />
        </div>
        <h3 className="text-xl font-bold font-outfit uppercase tracking-tight text-white">
          Super Admin Governance Restricted
        </h3>
        <p className="text-xs text-slate-400 font-mono leading-relaxed">
          The Admin Team Management module is strictly reserved for the Master Super Administrator
          (Farhan Ahmad). Subordinate moderators do not possess governance authorization to invite,
          reconfigure, or revoke administrative roles.
        </p>
      </div>
    );
  }

  const handleInviteSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inviteEmail.trim() || !inviteName.trim()) {
      setNotice({ text: 'Please fill out all required fields.', type: 'error' });
      return;
    }

    setActionLoading(true);
    setNotice(null);
    try {
      const headers = await getAdminAuthHeader();
      const res = await fetch(`${API_BASE}/api/admin/team/invite`, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          email: inviteEmail.trim(),
          name: inviteName.trim(),
          permissions: invitePerms,
        }),
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.detail || `Invite failed: HTTP ${res.status}`);
      }

      const newAdmin: AdminUser = await res.json();
      setTeam((prev) => [newAdmin, ...prev]);
      setNotice({ text: `Administrator invite sent for ${newAdmin.email}`, type: 'success' });
      setInviteModalOpen(false);
      setInviteEmail('');
      setInviteName('');
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Invite failed';
      setNotice({ text: msg, type: 'error' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleEditSave = async () => {
    if (!editingAdmin) return;
    setActionLoading(true);
    setNotice(null);
    try {
      const headers = await getAdminAuthHeader();
      const res = await fetch(`${API_BASE}/api/admin/team/${editingAdmin.id}`, {
        method: 'PATCH',
        headers,
        body: JSON.stringify({
          permissions: editPerms,
          is_active: editActive,
        }),
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.detail || `Update failed: HTTP ${res.status}`);
      }

      const updated: AdminUser = await res.json();
      setTeam((prev) => prev.map((a) => (a.id === updated.id ? updated : a)));
      setNotice({ text: `Updated permissions for ${updated.email}`, type: 'success' });
      setEditingAdmin(null);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Update failed';
      setNotice({ text: msg, type: 'error' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleDeleteAdmin = (admin: AdminUser) => {
    if (admin.is_super_admin) return;
    setAdminToRevoke(admin);
  };

  const handleConfirmDeleteAdmin = async () => {
    if (!adminToRevoke || adminToRevoke.is_super_admin) return;
    const admin = adminToRevoke;
    setActionLoading(true);
    setNotice(null);
    try {
      const headers = await getAdminAuthHeader();
      const res = await fetch(`${API_BASE}/api/admin/team/${admin.id}`, {
        method: 'DELETE',
        headers,
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.detail || `Deletion failed: HTTP ${res.status}`);
      }

      setTeam((prev) => prev.filter((a) => a.id !== admin.id));
      setNotice({ text: `Administrator ${admin.email} deleted successfully.`, type: 'success' });
      setAdminToRevoke(null);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Deletion failed';
      setNotice({ text: msg, type: 'error' });
    } finally {
      setActionLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 border-b border-slate-800 pb-5">
        <div>
          <div className="flex items-center gap-2">
            <Crown className="w-4 h-4 text-amber-400" />
            <span className="text-[11px] font-mono uppercase tracking-widest text-amber-400 font-bold">
              Master Governance // Super Admin Exclusive
            </span>
          </div>
          <h2 className="text-2xl font-black font-outfit uppercase tracking-tight text-white mt-1">
            Admin Team & RBAC Permissions
          </h2>
          <p className="text-xs text-slate-400 font-mono">
            Provision moderators, configure granular capability flags, inspect last logins, and audit access
          </p>
        </div>

        <div className="flex items-center gap-3">
          <button
            onClick={fetchTeam}
            disabled={loading}
            className="p-2.5 bg-slate-900 hover:bg-slate-800 border border-slate-700 text-slate-300 rounded-xl transition-all cursor-pointer active:scale-95"
            title="Refresh Team List"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin text-emerald-400' : ''}`} />
          </button>
          <button
            onClick={() => setInviteModalOpen(true)}
            className="px-4 py-2.5 bg-emerald-500 hover:bg-emerald-400 text-slate-950 text-xs font-black uppercase tracking-wider rounded-xl transition-all flex items-center gap-2 active:scale-95 shadow-lg shadow-emerald-950 cursor-pointer"
          >
            <UserPlus className="w-4 h-4" />
            Invite Admin / Mod
          </button>
        </div>
      </div>

      {notice && (
        <div
